/// <summary>
/// PricingAttribute of table <c>InventDim</c> field InventStatusId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimInventStatusId extends UPSPricingAttributeInventDim implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventStatusId);
}

public Set getAllowedValues()
{
    var       ret = new Set(Types::String);
    InventDim inventDim;

    while select inventDim
        group by InventStatusId
    {
        if (! ret.in(inventDim.InventStatusId))
        {
            ret.add(inventDim.InventStatusId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventStatusId));
    qbr.value(queryValue(_value));
}
